// Bộ ảnh 6 tay đua thú (vẽ bằng AI, đã tách nền + giữ thành phần chính mỗi ô,
// nén WebP nhúng base64 để đẩy GitHub trọn vẹn). Lưới 3x2, ô 560x420.
// Thứ tự: 0 Mèo Cam · 1 Thỏ Trắng · 2 Cáo Đỏ · 3 Gấu Trúc · 4 Chó Nâu · 5 Gà Vàng
export const RACER_SHEET = 'data:image/webp;base64,';
export const RACER_NAMES = ['Mèo Cam', 'Thỏ Trắng', 'Cáo Đỏ', 'Gấu Trúc', 'Chó Nâu', 'Gà Vàng'];
export function racerPos(i: number): string {
  const c = i % 3, r = Math.floor(i / 3);
  return `${c * 50}% ${r * 100}%`;
}
